class UserMessageCount(BaseModel):
    user: str
    count: int

channels = get_channels()
user_message_counts = {}

for channel in channels:
    messages = read_channel_messages(channel)
    for message in messages:
        if not message.recipient.startswith("#"):
            continue
        user = message.sender
        if user in user_message_counts:
            user_message_counts[user] += 1
        else:
            user_message_counts[user] = 1

if len(user_message_counts) == 0:
    raise ValueError("No channel messages found.")

user_message_count_list = [
    UserMessageCount(user=user, count=count)
    for user, count in user_message_counts.items()
]

max_count = max([umc.count for umc in user_message_count_list])
most_active_users = [umc.user for umc in user_message_count_list if umc.count == max_count]

# If there are multiple, pick the first one
most_active_user = most_active_users[0]

send_direct_message(
    recipient=most_active_user,
    body="Congrats on being the most active user!"
)
